import { useCallback, useEffect, useMemo, useState } from 'react'
import { Activity, ArrowDown, ArrowLeft, ArrowUp, Bell, BriefcaseBusiness, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, ClipboardCheck, Clock3, Download, FileText, Filter, HeartHandshake, LayoutDashboard, MapPin, Menu, MoreHorizontal, Plus, Search, Settings, ShieldCheck, SlidersHorizontal, Sparkles, TrendingUp, UserRound, UserRoundPlus, UsersRound, WalletCards, X } from 'lucide-react'
import { Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import * as api from './api.js'
import { timeAgo } from './api.js'
import './App.css'

const programs = ['Mental Wellness Program', 'Education Support Program', 'Women Skill Development', 'Healthcare Support Program', 'Livelihood Development Program', 'Community Nutrition Program']
const navigation = [
  { label: 'Dashboard', icon: LayoutDashboard }, { label: 'Projects', icon: BriefcaseBusiness }, { label: 'Events', icon: CalendarDays }, { label: 'Volunteers', icon: HeartHandshake }, { label: 'Beneficiaries', icon: UsersRound }, { label: 'Resources & Budget', icon: WalletCards }, { label: 'Reports', icon: FileText }, { label: 'Settings', icon: Settings },
]
const donutColors = ['#76b7a5', '#eab96a', '#7e9ac8', '#cf8c78', '#a6b66d', '#b79ad0', '#9aa5a0']
const statusClass = (status) => status.toLowerCase().replaceAll(' ', '-')

function App() {
  // Data now comes from the FastAPI backend instead of localStorage / hard-coded arrays.
  const [beneficiaries, setBeneficiaries] = useState([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState('')
  const [stats, setStats] = useState(null)
  const [statsError, setStatsError] = useState('')
  const [saving, setSaving] = useState(false)
  const [formErrors, setFormErrors] = useState({})
  const [toastType, setToastType] = useState('success')
  const [page, setPage] = useState('Dashboard')
  const [selected, setSelected] = useState(null)
  const [profileTab, setProfileTab] = useState('Overview')
  const [modal, setModal] = useState(null)
  const [editing, setEditing] = useState(null)
  const [toast, setToast] = useState('')
  const [query, setQuery] = useState('')
  const [globalSearch, setGlobalSearch] = useState('')
  const [filters, setFilters] = useState({ program: '', gender: '', age: '', city: '', status: '', date: '' })
  const [sort, setSort] = useState({ key: 'name', direction: 'asc' })
  const [period, setPeriod] = useState('6 Months')
  const [mobileMenu, setMobileMenu] = useState(false)
  const [assessment, setAssessment] = useState('')

  // Loads the beneficiary list and the dashboard statistics from the API.
  const loadData = useCallback(async (showSpinner = true) => {
    if (showSpinner) setLoading(true)
    const [list, statistics] = await Promise.allSettled([api.listBeneficiaries(), api.getStatistics()])
    if (list.status === 'fulfilled') {
      setLoadError('')
      // services/follow-ups are not in the database yet, so keep what was added this session
      setBeneficiaries((previous) => list.value.map((record) => {
        const old = previous.find((item) => item.id === record.id)
        return old ? { ...record, services: old.services, followUps: old.followUps } : record
      }))
    } else setLoadError(list.reason.message)
    if (statistics.status === 'fulfilled') { setStats(statistics.value); setStatsError('') } else setStatsError(statistics.reason.message)
    setLoading(false)
  }, [])
  useEffect(() => { loadData() }, [loadData])
  useEffect(() => { if (toast) { const timer = setTimeout(() => setToast(''), 3200); return () => clearTimeout(timer) } }, [toast])

  const activeRecord = beneficiaries.find((person) => person.id === selected)
  const filtered = useMemo(() => beneficiaries.filter((person) => {
    const text = `${person.name} ${person.code} ${person.phone} ${person.city}`.toLowerCase()
    const ageMatches = !filters.age || (filters.age === '0–12' ? person.age <= 12 : filters.age === '13–18' ? person.age >= 13 && person.age <= 18 : filters.age === '19–30' ? person.age >= 19 && person.age <= 30 : filters.age === '31–50' ? person.age >= 31 && person.age <= 50 : person.age >= 51)
    return text.includes(query.toLowerCase()) && (!filters.program || person.program === filters.program) && (!filters.gender || person.gender === filters.gender) && ageMatches && (!filters.city || person.city === filters.city) && (!filters.status || person.status === filters.status) && (!filters.date || person.registrationDate.includes(filters.date))
  }).sort((a, b) => `${a[sort.key]}`.localeCompare(`${b[sort.key]}`, undefined, { numeric: true }) * (sort.direction === 'asc' ? 1 : -1)), [beneficiaries, filters, query, sort])

  const go = (target) => { setPage(target); setSelected(null); setMobileMenu(false) }
  const showToast = (message, type = 'success') => { setToast(message); setToastType(type) }
  const openBeneficiaryForm = (record = null) => { setEditing(record); setFormErrors({}); setModal('beneficiary') }
  const saveBeneficiary = async (event) => {
    event.preventDefault()
    const values = Object.fromEntries(new FormData(event.currentTarget).entries())
    const errors = api.validateBeneficiary(values) // 1) check the form in the browser first
    setFormErrors(errors)
    if (Object.keys(errors).length) { showToast('Please fix the highlighted fields.', 'error'); event.currentTarget.elements[Object.keys(errors)[0]]?.focus(); return }
    setSaving(true)
    try { // 2) send it to the API, which validates again and saves to SQLite
      if (editing) {
        await api.updateBeneficiary(editing.id, { ...api.recordToFormValues(editing), ...values })
        showToast('Beneficiary information updated successfully.')
      } else {
        await api.createBeneficiary(values)
        showToast('Beneficiary successfully added.')
      }
      setModal(null)
      await loadData(false) // 3) reload list + dashboard numbers from the database
    } catch (error) {
      setFormErrors(error.fieldErrors || {}) // show the server's messages next to the fields
      showToast(error.message, 'error')
    } finally { setSaving(false) }
  }
  const openProfile = async (id) => {
    setSelected(id); setProfileTab('Overview'); setPage('Beneficiaries')
    try { // GET /api/beneficiaries/{id} - fetch the latest copy of this one beneficiary
      const fresh = await api.getBeneficiary(id)
      setBeneficiaries((items) => items.map((item) => item.id === id ? { ...item, ...fresh, services: item.services, followUps: item.followUps } : item))
    } catch (error) {
      showToast(error.message, 'error')
      if (error.status === 404) { setSelected(null); loadData(false) }
    }
  }
  const viewStatus = (status) => { setQuery(''); setFilters((old) => ({ ...old, status })); go('Beneficiaries') }
  const saveEntry = (event) => {
    event.preventDefault()
    const values = Object.fromEntries(new FormData(event.currentTarget).entries())
    setBeneficiaries((items) => items.map((item) => item.id === selected ? { ...item, [modal === 'service' ? 'services' : 'followUps']: modal === 'service' ? [...(item.services || []), { ...values }] : [...(item.followUps || []), { ...values, status: values.status || 'Pending' }] } : item))
    showToast(modal === 'service' ? 'Service added (this session only - services are not stored in the database yet).' : 'Follow-up added (this session only - follow-ups are not stored in the database yet).')
    setModal(null)
  }
  const deactivate = async () => {
    setSaving(true)
    try { // DELETE /api/beneficiaries/{id} - soft delete: the record stays, status becomes Inactive
      await api.deactivateBeneficiary(selected)
      setModal(null); showToast('Beneficiary deactivated.')
      await loadData(false)
    } catch (error) { showToast(error.message, 'error') } finally { setSaving(false) }
  }
  const saveAssessment = async (text) => {
    try {
      await api.updateBeneficiary(selected, { ...api.recordToFormValues(activeRecord), assessment: text })
      showToast('Needs assessment updated successfully.')
      await loadData(false)
    } catch (error) { showToast(error.message, 'error') }
  }
  const changeSort = (key) => setSort((value) => ({ key, direction: value.key === key && value.direction === 'asc' ? 'desc' : 'asc' }))

  return <div className="app-shell">
    <aside className={`sidebar ${mobileMenu ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><HeartHandshake size={22} /></div><div><b>HOPE</b><span>NGO MANAGEMENT</span></div><button className="icon-button mobile-close" onClick={() => setMobileMenu(false)} aria-label="Close navigation"><X size={18} /></button></div>
      <div className="workspace-label">WORKSPACE</div>
      <nav className="nav-list" aria-label="Main navigation">{navigation.map(({ label, icon: Icon }) => <button key={label} className={`nav-item ${page === label && !selected ? 'active' : ''}`} onClick={() => go(label)}><Icon size={18} strokeWidth={1.8} /><span>{label}</span>{label === 'Beneficiaries' && !loading && !loadError && <span className="nav-count">{beneficiaries.length}</span>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="help-box"><div className="help-icon"><CircleHelp size={18} /></div><div><strong>Need a hand?</strong><span>Visit the help centre</span></div><ChevronRight size={16} /></div><div className="user-block"><div className="avatar avatar-green">AS</div><div className="user-meta"><strong>Ananya Shah</strong><span>NGO Administrator</span></div><button className="icon-button" aria-label="User menu"><MoreHorizontal size={19} /></button></div><button className="logout-button" onClick={() => showToast('You are signed in as the demo administrator.')}><ShieldCheck size={15} /> Admin workspace</button></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><button className="icon-button menu-toggle" aria-label="Open navigation" onClick={() => setMobileMenu(true)}><Menu size={21} /></button><div className="breadcrumbs"><span>Workspace</span><ChevronRight size={14} /><strong>{selected ? 'Beneficiary profile' : page}</strong></div><div className="topbar-tools"><label className="global-search"><Search size={16} /><input placeholder="Search anything..." value={globalSearch} onChange={(e) => { setGlobalSearch(e.target.value); if (e.target.value) { setPage('Beneficiaries'); setSelected(null); setQuery(e.target.value) } }} /><kbd>⌘ K</kbd></label><button className="icon-button notification-button" aria-label="Notifications" onClick={() => showToast('You are all caught up on notifications.')}><Bell size={18} /><i /></button><div className="top-user"><div className="avatar avatar-green">AS</div><ChevronDown size={14} /></div></div></header>
      <div className="page-content">
        {selected && activeRecord ? <ProfilePage person={activeRecord} tab={profileTab} setTab={setProfileTab} onBack={() => { setSelected(null); setPage('Beneficiaries') }} onEdit={() => openBeneficiaryForm(activeRecord)} onAddService={() => setModal('service')} onAddFollowUp={() => setModal('followup')} onReport={() => setModal('report')} onDeactivate={() => setModal('deactivate')} setModal={setModal} saveAssessment={saveAssessment} openTab={setProfileTab} /> : page === 'Dashboard' ? <Dashboard stats={stats} statsLoading={loading} statsError={statsError} retry={() => loadData()} period={period} setPeriod={setPeriod} navigate={go} viewStatus={viewStatus} addBeneficiary={() => openBeneficiaryForm()} showToast={showToast} /> : page === 'Beneficiaries' ? <BeneficiariesPage beneficiaries={beneficiaries} loading={loading} loadError={loadError} retry={() => loadData()} stats={stats} filtered={filtered} query={query} setQuery={setQuery} filters={filters} setFilters={setFilters} clearFilters={() => { setFilters({ program: '', gender: '', age: '', city: '', status: '', date: '' }); setQuery('') }} sort={sort} changeSort={changeSort} addBeneficiary={() => openBeneficiaryForm()} openProfile={openProfile} /> : <OtherPage page={page} navigate={go} />}
      </div>
    </main>
    {modal && <Modal type={modal} editing={editing} person={activeRecord} errors={formErrors} saving={saving} close={() => setModal(null)} saveBeneficiary={saveBeneficiary} saveEntry={saveEntry} deactivate={deactivate} showToast={showToast} />}
    {toast && <div className={`toast ${toastType === 'error' ? 'toast-error' : ''}`} role={toastType === 'error' ? 'alert' : 'status'}><span className="toast-check">{toastType === 'error' ? '!' : <Check size={16} />}</span>{toast}<button onClick={() => setToast('')} aria-label="Dismiss notification"><X size={15} /></button></div>}
  </div>
}

function PageHeading({ eyebrow, title, subtitle, action }) { return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div> }
function Dashboard({ stats, statsLoading, statsError, retry, period, setPeriod, navigate, viewStatus, addBeneficiary, showToast }) {
  // Show a number, "…" while loading, or "—" if the API could not be reached.
  const num = (value) => stats ? Number(value).toLocaleString() : statsLoading ? '…' : '—'
  const today = new Date()
  const dateLabel = `${today.toLocaleDateString('en-US', { weekday: 'long' })}, ${today.getDate()} ${today.toLocaleDateString('en-US', { month: 'long' })} ${today.getFullYear()}`.toUpperCase()

  // 1) Cards calculated from the SQLite database through GET /api/dashboard/statistics
  const liveCards = [
    { label: 'Total beneficiaries', value: stats?.total_beneficiaries, note: 'registered in total', icon: UsersRound, tone: 'mint', onClick: () => viewStatus('') },
    { label: 'Active beneficiaries', value: stats?.active_beneficiaries, note: 'status: Active', icon: Activity, tone: 'blue', onClick: () => viewStatus('Active') },
    { label: 'Inactive beneficiaries', value: stats?.inactive_beneficiaries, note: 'status: Inactive', icon: UserRound, tone: 'rose', onClick: () => viewStatus('Inactive') },
    { label: 'Recently added', value: stats?.recent_beneficiaries, note: `last ${stats?.recent_days ?? 30} days`, icon: UserRoundPlus, tone: 'lime', onClick: () => navigate('Beneficiaries') },
  ]
  // 2) Cards that belong to other modules - there is no data for them yet, so nothing is invented.
  const pendingCards = [
    { label: 'Active projects', icon: BriefcaseBusiness, tone: 'blue', module: 'Projects' },
    { label: 'Upcoming events', icon: CalendarDays, tone: 'amber', module: 'Events' },
    { label: 'Active volunteers', icon: HeartHandshake, tone: 'rose', module: 'Volunteers' },
    { label: 'Funds utilized', icon: WalletCards, tone: 'lavender', module: 'Budget' },
    { label: 'People impacted', icon: TrendingUp, tone: 'lime', module: 'Reports' },
  ]

  const donutData = (stats?.by_program || []).map((item, index) => ({ name: item.program.replace(' Program', ''), value: item.count, color: donutColors[index % donutColors.length] }))
  const series = stats?.registrations?.[period]
  const change = series?.change_percent
  const changeLabel = change === null || change === undefined ? '—' : `${change > 0 ? '+' : ''}${change}%`
  const activity = (stats?.recent_activity || []).slice(0, 4)
  // Wording for empty panels: still loading, API unreachable, or genuinely no data.
  const emptyText = (whenEmpty) => statsLoading ? ['Loading…', 'Fetching data from the database.'] : stats ? whenEmpty : ['Data unavailable', 'The data could not be loaded from the backend.']
  const donutEmpty = emptyText(['No beneficiaries yet', 'Add a beneficiary to see the programme breakdown.'])
  const activityEmpty = emptyText(['No activity yet', 'New registrations and updates will show up here.'])
  const attentionEmpty = emptyText(['All caught up', 'No beneficiaries need a follow-up right now.'])
  const followUps = stats?.follow_up_required || 0

  return <>
    <PageHeading eyebrow={dateLabel} title="Good morning, Ananya" subtitle="Here’s what’s happening across your programmes today." action={<button className="button button-primary" onClick={addBeneficiary}><Plus size={16} /> Add beneficiary</button>} />
    {statsError && <div className="api-alert" role="alert"><span>{statsError}</span><button className="text-button" onClick={retry}>Try again</button></div>}
    <div className="kpi-group-label">Beneficiary statistics · live from the database</div>
    <div className="kpi-grid kpi-grid-live">{liveCards.map(({ label, value, note, icon: Icon, tone, onClick }) => <button key={label} className="kpi-card" onClick={onClick}><div className={`kpi-icon ${tone}`}><Icon size={18} /></div><div className="kpi-label">{label}<span className="metric-more"><MoreHorizontal size={16} /></span></div><strong className="kpi-value">{num(value)}</strong><div className="kpi-foot"><span className="trend-neutral">{note}</span></div></button>)}</div>
    <div className="kpi-group-label">Other modules · not connected yet</div>
    <div className="kpi-grid kpi-grid-pending">{pendingCards.map(({ label, icon: Icon, tone, module }) => <div key={label} className="kpi-card kpi-pending"><div className={`kpi-icon ${tone}`}><Icon size={18} /></div><div className="kpi-label">{label}</div><strong className="kpi-value">—</strong><div className="kpi-foot"><span className="trend-neutral">{module} module pending</span></div></div>)}</div>
    <section className="section-block"><div className="section-title-row"><div><h2>Beneficiary overview</h2><p>Reach and registrations across all programmes</p></div><button className="text-button" onClick={() => navigate('Beneficiaries')}>View beneficiaries <ArrowRightIcon /></button></div>
      <div className="overview-grid"><article className="panel category-panel"><div className="panel-head"><div><h3>Beneficiaries by programme</h3><p>{stats ? `${stats.total_beneficiaries.toLocaleString()} people registered` : statsLoading ? 'Loading…' : 'Data unavailable'}</p></div><button className="icon-button subtle" aria-label="More chart options"><MoreHorizontal size={19} /></button></div>
        {donutData.length ? <div className="donut-layout"><div className="donut-wrap"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={donutData} dataKey="value" nameKey="name" innerRadius="67%" outerRadius="92%" paddingAngle={3} stroke="none">{donutData.map((item) => <Cell key={item.name} fill={item.color} />)}</Pie><Tooltip formatter={(value) => [`${value} people`, 'Beneficiaries']} /></PieChart></ResponsiveContainer><div className="donut-center"><strong>{stats.total_beneficiaries.toLocaleString()}</strong><span>beneficiaries</span></div></div><div className="legend-list">{donutData.map((item) => <div className="legend-item" key={item.name}><span className="legend-dot" style={{ background: item.color }} /><span>{item.name}</span><strong>{item.value}</strong></div>)}</div></div>
          : <div className="empty-state"><UsersRound size={22} /><strong>{donutEmpty[0]}</strong><span>{donutEmpty[1]}</span></div>}</article>
        <article className="panel registrations-panel"><div className="panel-head"><div><h3>Registration activity</h3><p>New beneficiary registrations over time</p></div><select className="period-select" value={period} onChange={(e) => setPeriod(e.target.value)} aria-label="Registration time period">{['7 Days', '30 Days', '6 Months', '1 Year'].map((value) => <option key={value}>{value}</option>)}</select></div>
          {series ? <><div className="line-legend"><span /><b>{series.total} new registrations</b><strong>{changeLabel}</strong><small>vs. previous period</small></div><div className="line-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={series.points} margin={{ top: 14, right: 8, bottom: 0, left: -20 }}><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: '#87918d', fontSize: 11 }} dy={9} /><YAxis hide /><Tooltip formatter={(value) => [value, 'Registrations']} contentStyle={{ border: '1px solid #e4e9e5', borderRadius: 8, boxShadow: '0 8px 22px #13261c12' }} /><Line type="monotone" dataKey="count" stroke="#3d8065" strokeWidth={2.5} dot={{ fill: '#fff', stroke: '#3d8065', strokeWidth: 2, r: 4 }} activeDot={{ r: 5 }} /></LineChart></ResponsiveContainer></div></>
            : <div className="empty-state"><TrendingUp size={22} /><strong>{statsLoading ? 'Loading chart…' : 'Chart unavailable'}</strong><span>{statsLoading ? 'Fetching data from the database.' : 'Registration data could not be loaded.'}</span></div>}</article></div>
    </section>
    <section className="section-block"><div className="section-title-row"><div><h2>Programme delivery</h2><p>Activity across projects and events</p></div><span className="updated-label"><span className="live-dot" /> {statsLoading ? 'Loading…' : statsError ? 'Offline' : 'Live from database'}</span></div><div className="delivery-grid"><article className="panel project-panel"><div className="panel-head"><div><h3>Active projects</h3><p>Not connected yet</p></div><button className="text-button" onClick={() => navigate('Projects')}>All projects <ArrowRightIcon /></button></div><div className="empty-state"><BriefcaseBusiness size={22} /><strong>Projects module not connected</strong><span>Project progress will appear here once the Projects module has data.</span></div></article>
        <article className="panel events-panel"><div className="panel-head"><div><h3>Coming up</h3><p>Not connected yet</p></div><button className="text-button" onClick={() => navigate('Events')}>All events <ArrowRightIcon /></button></div><div className="empty-state"><CalendarDays size={22} /><strong>Events module not connected</strong><span>Upcoming events will appear here once the Events module has data.</span></div></article></div></section>
    <section className="section-block bottom-grid"><article className="panel activity-panel"><div className="panel-head"><div><h3>Recent activity</h3><p>Latest beneficiary registrations and updates</p></div><button className="icon-button subtle" aria-label="Activity options"><MoreHorizontal size={19} /></button></div><div className="activity-list">{activity.length ? activity.map((item) => item.action === 'registered' ? <ActivityItem key={item.id} icon={UserRoundPlus} tone="mint" title="New beneficiary registered" description={item.program ? `${item.name} added to ${item.program}` : `${item.name} was registered`} time={timeAgo(item.timestamp)} /> : <ActivityItem key={item.id} icon={ClipboardCheck} tone="blue" title="Beneficiary profile updated" description={`${item.name}’s information was updated`} time={timeAgo(item.timestamp)} />) : <div className="empty-state"><ClipboardCheck size={22} /><strong>{activityEmpty[0]}</strong><span>{activityEmpty[1]}</span></div>}</div></article><article className="panel tasks-panel"><div className="panel-head"><div><h3>Needs attention</h3><p>Tasks to keep support moving</p></div><span className="task-count">{stats ? followUps : '—'}</span></div>{followUps > 0 ? <button className="task-row" onClick={() => viewStatus('Follow-up Required')}><span className="task-check rose"><Check size={12} /></span><span><strong>Follow-up required</strong><small>{followUps} beneficiar{followUps === 1 ? 'y' : 'ies'}</small></span><ChevronRight size={15} /></button> : <div className="empty-state"><Check size={22} /><strong>{attentionEmpty[0]}</strong><span>{attentionEmpty[1]}</span></div>}</article></section>
    <div className="quick-actions"><div><Sparkles size={17} /><strong>Quick actions</strong></div><button onClick={addBeneficiary}><Plus size={15} /> Add beneficiary</button><button onClick={() => navigate('Projects')}><Plus size={15} /> Create project</button><button onClick={() => navigate('Events')}><Plus size={15} /> Create event</button><button onClick={() => navigate('Volunteers')}><Plus size={15} /> Add volunteer</button><button onClick={() => showToast('Donation entry form is ready for the next prototype iteration.')}><Plus size={15} /> Record donation</button></div>
  </>
}
function ArrowRightIcon() { return <ChevronRight size={15} /> }
function ActivityItem({ icon: Icon, tone, title, description, time }) { return <div className="activity-item"><div className={`activity-icon ${tone}`}><Icon size={15} /></div><div className="activity-copy"><strong>{title}</strong><span>{description}</span></div><time>{time}</time></div> }

function BeneficiariesPage({ beneficiaries, loading, loadError, retry, stats, filtered, query, setQuery, filters, setFilters, clearFilters, sort, changeSort, addBeneficiary, openProfile }) {
  const setFilter = (key, value) => setFilters((old) => ({ ...old, [key]: value }))
  // These tiles come from GET /api/dashboard/statistics (calculated in SQLite).
  const num = (value) => stats ? Number(value).toLocaleString() : loading ? '…' : '—'
  const tiles = [{ label: 'Total beneficiaries', value: num(stats?.total_beneficiaries), tone: 'mint' }, { label: 'Active beneficiaries', value: num(stats?.active_beneficiaries), tone: 'blue' }, { label: 'Inactive beneficiaries', value: num(stats?.inactive_beneficiaries), tone: 'rose' }, { label: `Added in last ${stats?.recent_days ?? 30} days`, value: num(stats?.recent_beneficiaries), tone: 'amber' }, { label: 'Follow-up required', value: num(stats?.follow_up_required), tone: 'lavender' }]
  const registrationMonths = [...new Set(beneficiaries.map((person) => person.registrationDate.slice(3, 6)).filter(Boolean))]
  const headers = [['id', 'Beneficiary ID'], ['name', 'Name'], ['age', 'Age'], ['gender', 'Gender'], ['phone', 'Contact'], ['city', 'Location'], ['program', 'Programme'], ['status', 'Status'], ['updatedAt', 'Last activity']]
  return <>
    <PageHeading eyebrow="PEOPLE & PROGRAMMES" title="Beneficiaries" subtitle="Manage beneficiary information, participation and support history." action={<button className="button button-primary" onClick={addBeneficiary}><Plus size={16} /> Add beneficiary</button>} />
    <div className="beneficiary-stats">{tiles.map((stat) => <div className="stat-tile" key={stat.label}><span className={`stat-dot ${stat.tone}`} /><span>{stat.label}</span><strong>{stat.value}</strong></div>)}</div>
    <section className="panel beneficiary-table-panel"><div className="table-heading"><div><h2>All beneficiaries <span>{filtered.length}</span></h2><p>A central record of the people and families you support.</p></div><button className="button button-secondary" onClick={() => window.print()}><Download size={15} /> Export list</button></div>
      <div className="filter-toolbar"><label className="table-search"><Search size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search name, ID, phone or location..." /><kbd>/</kbd></label><div className="filter-controls"><div className="filter-caption"><SlidersHorizontal size={15} /> Filters</div><FilterSelect value={filters.program} onChange={(value) => setFilter('program', value)} placeholder="Programme" options={programs} /><FilterSelect value={filters.gender} onChange={(value) => setFilter('gender', value)} placeholder="Gender" options={['Female', 'Male', 'Other']} /><FilterSelect value={filters.age} onChange={(value) => setFilter('age', value)} placeholder="Age group" options={['0–12', '13–18', '19–30', '31–50', '51+']} /><FilterSelect value={filters.city} onChange={(value) => setFilter('city', value)} placeholder="Location" options={[...new Set(beneficiaries.map((person) => person.city))].sort()} /><FilterSelect value={filters.status} onChange={(value) => setFilter('status', value)} placeholder="Status" options={['Active', 'Inactive', 'Follow-up Required', 'Completed']} /><FilterSelect value={filters.date} onChange={(value) => setFilter('date', value)} placeholder="Registration month" options={registrationMonths} />{Object.values(filters).some(Boolean) || query ? <button className="clear-filters" onClick={clearFilters}>Clear</button> : null}</div></div>
      <div className="table-scroll"><table className="beneficiary-table"><thead><tr>{headers.map(([key, label]) => <th key={key}><button className="sort-button" onClick={() => changeSort(key)}>{label}{sort.key === key ? sort.direction === 'asc' ? <ArrowDown size={12} /> : <ArrowUp size={12} /> : <ArrowDown size={11} className="sort-muted" />}</button></th>)}<th><span className="sr-only">Actions</span></th></tr></thead><tbody>{filtered.map((person, index) => <tr key={person.id}><td className="id-cell">{person.code}</td><td><button className="person-link" onClick={() => openProfile(person.id)}><span className={`table-avatar avatar-tone-${index % 5}`}>{person.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</span><span><strong>{person.name}</strong><small>{person.email || person.primaryNeed}</small></span></button></td><td>{person.age}</td><td>{person.gender}</td><td>{person.phone}</td><td>{person.city}</td><td><span className="program-cell">{person.program.replace(' Program', '')}</span></td><td><span className={`status-pill ${statusClass(person.status)}`}><i />{person.status}</span></td><td>{person.lastActivity}</td><td><button className="icon-button row-action" title="View profile" onClick={() => openProfile(person.id)}><ChevronRight size={17} /></button></td></tr>)}</tbody></table>{loading && <div className="empty-state"><span className="spinner" /><strong>Loading beneficiaries…</strong><span>Fetching records from the database.</span></div>}
        {!loading && loadError && <div className="empty-state"><UsersRound size={24} /><strong>Couldn’t load beneficiaries</strong><span>{loadError}</span><button className="text-button" onClick={retry}>Try again</button></div>}
        {!loading && !loadError && filtered.length === 0 && (beneficiaries.length === 0
          ? <div className="empty-state"><UsersRound size={24} /><strong>No beneficiaries yet</strong><span>Add your first beneficiary to get started.</span><button className="text-button" onClick={addBeneficiary}>Add beneficiary</button></div>
          : <div className="empty-state"><UsersRound size={24} /><strong>No beneficiaries found</strong><span>Try adjusting your search or filters.</span><button className="text-button" onClick={clearFilters}>Clear filters</button></div>)}</div>
      <div className="table-footer"><span>Showing <strong>{filtered.length ? 1 : 0}–{filtered.length}</strong> of <strong>{filtered.length}</strong> beneficiaries</span><div className="pagination"><button aria-label="Previous page" disabled><ChevronLeft size={16} /></button><button className="page-current">1</button><button aria-label="Next page" disabled><ChevronRight size={16} /></button></div></div>
    </section>
    <div className="data-note"><ShieldCheck size={14} /><span>Beneficiary information is securely managed and visible only to your organisation.</span></div>
  </>
}
function FilterSelect({ value, onChange, placeholder, options }) { return <label className={`filter-select ${value ? 'filter-selected' : ''}`}><select value={value} onChange={(e) => onChange(e.target.value)} aria-label={placeholder}><option value="">{placeholder}</option>{options.map((option) => <option key={option}>{option}</option>)}</select><ChevronDown size={13} /></label> }

function ProfilePage({ person, tab, setTab, onBack, onEdit, onAddService, onAddFollowUp, onReport, onDeactivate, setModal, saveAssessment, openTab }) {
  const tabs = ['Overview', 'Personal information', 'Needs assessment', 'Project participation', 'Event participation', 'Services provided', 'Follow-ups', 'Progress history', 'Documents', 'Reports']
  const [editingAssessment, setEditingAssessment] = useState(false)
  const [assessmentText, setAssessmentText] = useState(person.assessment)
  useEffect(() => { setAssessmentText(person.assessment); setEditingAssessment(false) }, [person.id, person.assessment])
  const saveNeeds = () => { saveAssessment(assessmentText); setEditingAssessment(false) }
  return <>
    <button className="back-link" onClick={onBack}><ArrowLeft size={15} /> Back to beneficiaries</button>
    <div className="profile-heading"><div className="profile-identity"><div className="profile-avatar">{person.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</div><div><div className="profile-id">BENEFICIARY PROFILE <span>·</span> {person.code}</div><div className="profile-name-row"><h1>{person.name}</h1><span className={`status-pill ${statusClass(person.status)}`}><i />{person.status}</span></div><p><MapPin size={14} />{person.city}, {person.state || 'Maharashtra'}<span>·</span>Enrolled {person.registrationDate}</p></div></div><div className="profile-actions"><button className="button button-secondary" onClick={onEdit}>Edit beneficiary</button><button className="button button-primary" onClick={onAddFollowUp}><Plus size={15} /> Add follow-up</button><button className="icon-button profile-more" aria-label="More beneficiary actions" onClick={() => onDeactivate()}><MoreHorizontal size={19} /></button></div></div>
    <div className="profile-tabs">{tabs.map((item) => <button key={item} className={tab === item ? 'tab-active' : ''} onClick={() => setTab(item)}>{item}</button>)}</div>
    {tab === 'Overview' && <div className="profile-body"><div className="profile-main-column"><section className="panel profile-section"><div className="section-heading"><div><h2>Beneficiary overview</h2><p>A snapshot of personal details and current support</p></div><button className="text-button" onClick={() => setTab('Personal information')}>Full profile <ChevronRight size={15} /></button></div><div className="detail-grid"><Detail label="Age" value={`${person.age} years`} /><Detail label="Gender" value={person.gender} /><Detail label="Location" value={`${person.city}, Maharashtra`} /><Detail label="Primary need" value={person.primaryNeed} /><Detail label="Current programme" value={person.program} /><Detail label="Registration date" value={person.registrationDate} /><Detail label="Assigned staff" value={person.assignedStaff || 'Anjali Joshi'} /><Detail label="Phone number" value={person.phone} /></div><div className="summary-box"><div className="summary-icon"><HeartHandshake size={17} /></div><div><strong>Beneficiary summary</strong><p>{person.assessment || `${person.name.split(' ')[0]} is enrolled in the ${person.program} and currently receiving community support.`}</p></div></div></section><section className="panel profile-section"><div className="section-heading"><div><h2>Needs assessment</h2><p>Current priorities and support plan</p></div><button className="text-button" onClick={() => setTab('Needs assessment')}>View assessment <ChevronRight size={15} /></button></div><div className="need-highlight"><span className="need-label">PRIMARY NEED</span><strong>{person.primaryNeed}</strong><span className="urgency-pill">{person.urgency || 'Medium'} priority</span></div><p className="assessment-copy">{person.needDescription || 'Ongoing support and access to community services.'}</p></section><section className="panel profile-section"><div className="section-heading"><div><h2>Recent support</h2><p>Services and follow-ups for {person.name.split(' ')[0]}</p></div><button className="text-button" onClick={() => setTab('Services provided')}>View history <ChevronRight size={15} /></button></div><div className="recent-support-row"><div className="support-icon"><HeartHandshake size={16} /></div><div><strong>{person.services?.[0]?.type || person.services?.[0] || 'Counselling Session'}</strong><span>Provided by Anjali Joshi · 25 Sep 2026</span></div><span className="status-pill completed">Completed</span></div></section></div><aside className="profile-side-column"><section className="panel profile-side-card"><div className="side-card-title"><h3>Programme participation</h3><button className="icon-button subtle" aria-label="Programme options"><MoreHorizontal size={17} /></button></div><div className="program-card-mini"><div className="program-mini-icon"><BriefcaseBusiness size={16} /></div><div><strong>{person.program}</strong><span>Participant · Since {person.registrationDate}</span></div></div><div className="mini-progress-label"><span>Programme progress</span><strong>72%</strong></div><div className="progress-track"><i style={{ width: '72%' }} /></div><button className="full-width-link" onClick={() => setTab('Project participation')}>View programme details <ChevronRight size={15} /></button></section><section className="panel profile-side-card"><div className="side-card-title"><h3>Upcoming follow-up</h3><Clock3 size={16} className="muted-icon" /></div><div className="upcoming-date"><div className="calendar-tile"><span>OCT</span><strong>10</strong></div><div><strong>{person.followUps?.find((item) => item.status !== 'Completed')?.reason || 'Counselling follow-up'}</strong><span>10 Oct 2026 · Anjali Joshi</span></div></div><button className="full-width-link" onClick={onAddFollowUp}>Schedule follow-up <ChevronRight size={15} /></button></section><section className="report-callout"><div className="report-callout-icon"><FileText size={17} /></div><div><strong>Beneficiary report</strong><span>Generate a summary of support and progress.</span></div><button onClick={onReport} aria-label="Generate beneficiary report"><ChevronRight size={17} /></button></section><button className="deactivate-link" onClick={onDeactivate}>Deactivate beneficiary</button></aside></div>}
    {tab === 'Personal information' && <section className="panel profile-section standalone-section"><div className="section-heading"><div><h2>Personal information</h2><p>Identity and contact details on record</p></div><button className="button button-secondary" onClick={onEdit}>Edit information</button></div><div className="detail-grid detail-grid-wide">{[['Full name', person.name], ['Date of birth', person.dob || 'Not provided'], ['Age', `${person.age} years`], ['Gender', person.gender], ['Phone number', person.phone], ['Email address', person.email || 'Not provided'], ['Address', person.address || person.city], ['City / State', `${person.city}, ${person.state || 'Maharashtra'}`], ['Emergency contact', person.emergency || 'Not provided'], ['Marital status', person.marital || 'Not provided'], ['Occupation', person.occupation || 'Not provided'], ['Family members', person.familyMembers || 'Not provided']].map(([label, value]) => <Detail key={label} label={label} value={value} />)}</div></section>}
    {tab === 'Needs assessment' && <section className="panel profile-section standalone-section"><div className="section-heading"><div><h2>Needs assessment</h2><p>Assessment details and current support priorities</p></div>{editingAssessment ? <div className="inline-actions"><button className="button button-secondary" onClick={() => { setEditingAssessment(false); setAssessmentText(person.assessment) }}>Cancel</button><button className="button button-primary" onClick={saveNeeds}>Save assessment</button></div> : <button className="button button-secondary" onClick={() => setEditingAssessment(true)}>Update assessment</button>}</div><div className="assessment-detail-grid"><Detail label="Primary need" value={person.primaryNeed} /><Detail label="Secondary needs" value={person.secondaryNeeds || 'Community support'} /><Detail label="Priority level" value={person.urgency || 'Medium'} /><Detail label="Assessment date" value="20 Jun 2026" /><Detail label="Assessed by" value={person.assignedStaff || 'Anjali Joshi'} /><Detail label="Current programme" value={person.program} /></div><div className="assessment-field"><label>Current situation and support requirements</label>{editingAssessment ? <textarea rows="5" value={assessmentText} onChange={(e) => setAssessmentText(e.target.value)} /> : <p>{person.assessment || person.needDescription || 'Ongoing support and access to community services.'}</p>}</div><div className="assessment-detail-grid"><Detail label="Family situation" value="Lives with family; support network available" /><Detail label="Financial situation" value="Needs periodic assistance" /><Detail label="Health / wellbeing" value="Regular check-ins recommended" /></div></section>}
    {tab === 'Project participation' && <ProfileTable title="Project participation" subtitle="Programmes and projects this beneficiary has participated in" columns={['Project', 'Role / participation', 'Start date', 'End date', 'Status', 'Outcome']} rows={[[person.program, 'Participant', person.registrationDate, 'Ongoing', 'Active', 'Ongoing support'], ['Community Outreach Initiative', 'Community member', '02 Aug 2026', 'Ongoing', 'Active', 'Regular participation']]} />}
    {tab === 'Event participation' && <ProfileTable title="Event participation" subtitle="Events attended and feedback shared" columns={['Event', 'Date', 'Location', 'Attendance', 'Feedback']} rows={[["Mental Health Awareness Workshop", '05 Sep 2026', 'Pune', 'Present', 'Positive'], ['Community Health Camp', '18 Aug 2026', person.city, 'Present', 'Helpful']]} />}
    {tab === 'Services provided' && <><div className="profile-section-actions"><div><h2>Services provided</h2><p>A history of support received by this beneficiary</p></div><button className="button button-primary" onClick={onAddService}><Plus size={15} /> Add service</button></div><ProfileTable title="" subtitle="" columns={['Service', 'Date', 'Provided by', 'Status', 'Remarks']} rows={(person.services || []).map((service) => typeof service === 'string' ? [service, '25 Sep 2026', 'Anjali Joshi', 'Completed', 'Support delivered'] : [service.type, service.date, service.provider, service.status, service.remarks || service.description])} /></>}
    {tab === 'Follow-ups' && <><div className="profile-section-actions"><div><h2>Follow-ups</h2><p>Scheduled check-ins and beneficiary progress</p></div><button className="button button-primary" onClick={onAddFollowUp}><Plus size={15} /> Schedule follow-up</button></div><ProfileTable title="" subtitle="" columns={['Follow-up date', 'Reason', 'Assigned staff', 'Status', 'Notes', 'Next follow-up']} rows={(person.followUps || []).map((item) => [item.date, item.reason, item.staff, item.status, item.notes, item.next])} /></>}
    {tab === 'Progress history' && <section className="panel profile-section standalone-section"><div className="section-heading"><div><h2>Progress history</h2><p>Key moments in {person.name.split(' ')[0]}’s support journey</p></div></div><div className="timeline">{(person.progress || []).map((item, index) => <div className="timeline-item" key={`${item}-${index}`}><div className="timeline-marker"><Check size={12} /></div><time>{['15 Jun 2026', '20 Jun 2026', '05 Jul 2026', '10 Aug 2026', '25 Sep 2026'][index % 5]}</time><strong>{item}</strong><p>Recorded by Anjali Joshi</p></div>)}</div></section>}
    {tab === 'Documents' && <><div className="profile-section-actions"><div><h2>Documents</h2><p>Identity, assessment and supporting files</p></div><button className="button button-primary" onClick={() => setModal('document')}><Plus size={15} /> Upload document</button></div><ProfileTable title="" subtitle="" columns={['Document name', 'Type', 'Uploaded date', 'Status', 'Action']} rows={(person.documents || []).map((name) => [name, 'PDF', '15 Jun 2026', 'Verified', 'View'])} /></>}
    {tab === 'Reports' && <section className="panel report-tab-panel"><div className="report-tab-icon"><FileText size={23} /></div><div><h2>Beneficiary report</h2><p>Bring personal information, needs, participation, services and progress together in one summary.</p><button className="button button-primary" onClick={onReport}><FileText size={15} /> Generate report</button></div></section>}
  </>
}
function Detail({ label, value }) { return <div className="detail-item"><span>{label}</span><strong>{value || 'Not provided'}</strong></div> }
function ProfileTable({ title, subtitle, columns, rows }) { return <section className="panel profile-table-panel">{title && <div className="table-heading"><div><h2>{title}</h2><p>{subtitle}</p></div></div>}<div className="table-scroll"><table className="data-table"><thead><tr>{columns.map((column) => <th key={column}>{column}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row, i) => <tr key={`${row[0]}-${i}`}>{row.map((value, j) => <td key={j}>{j === 3 && ['Active', 'Completed', 'Verified', 'Pending', 'Rescheduled'].includes(value) ? <span className={`status-pill ${statusClass(value)}`}><i />{value}</span> : value === 'View' ? <button className="text-button" onClick={() => window.print()}>View <ChevronRight size={14} /></button> : value || '—'}</td>)}</tr>) : <tr><td colSpan={columns.length} className="empty-table">No records have been added yet.</td></tr>}</tbody></table></div></section> }

function OtherPage({ page, navigate }) { const info = { Projects: ['Programme portfolio', 'Track delivery, progress and communities reached across active projects.', BriefcaseBusiness], Events: ['Events & outreach', 'Coordinate workshops, community health camps and local outreach.', CalendarDays], Volunteers: ['Volunteer network', 'Coordinate volunteer capacity and community-led support.', HeartHandshake], 'Resources & Budget': ['Resources & budget', 'Monitor grants, allocations and programme expenditure.', WalletCards], Reports: ['Impact reports', 'Review beneficiary outcomes and programme reach.', FileText], Settings: ['Organisation settings', 'Manage team access and organisation preferences.', Settings] }[page] || ['Workspace', 'Your organisation’s central workspace.', LayoutDashboard]; const Icon = info[2]; return <div className="other-view"><PageHeading eyebrow="HOPE WORKSPACE" title={info[0]} subtitle={info[1]} /><div className="other-panel"><div className="other-icon"><Icon size={23} /></div><h2>{page} workspace</h2><p>This area is ready for your team. The dashboard and beneficiary management workflows are available now.</p><button className="button button-primary" onClick={() => navigate('Dashboard')}>Return to dashboard</button></div></div> }

function Modal({ type, editing, person, errors = {}, saving = false, close, saveBeneficiary, saveEntry, deactivate, showToast }) {
  const title = type === 'beneficiary' ? editing ? 'Edit beneficiary' : 'Add beneficiary' : type === 'service' ? 'Add service record' : type === 'followup' ? 'Schedule a follow-up' : type === 'deactivate' ? 'Deactivate beneficiary' : type === 'report' ? 'Beneficiary report' : 'Upload document'
  useEffect(() => { const onKey = (event) => { if (event.key === 'Escape') close() }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey) }, [close])
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) close() }}><section className={`modal-card ${type === 'beneficiary' ? 'beneficiary-modal' : ''} ${type === 'report' ? 'report-modal' : ''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-header"><div><span className="modal-eyebrow">{type === 'beneficiary' ? 'BENEFICIARY MANAGEMENT' : 'HOPE WORKSPACE'}</span><h2 id="modal-title">{title}</h2></div><button className="icon-button" aria-label="Close dialog" onClick={close}><X size={19} /></button></div>
    {type === 'beneficiary' && <form onSubmit={saveBeneficiary} className="beneficiary-form" noValidate><FormSection title="Personal information"><Field label="Full name" required name="name" defaultValue={editing?.name} error={errors.name} /><Field label="Date of birth" name="dob" type="date" defaultValue={editing?.dobISO} error={errors.dob} /><Field label="Age" name="age" type="number" min="0" max="120" required defaultValue={editing?.age} error={errors.age} /><Field label="Gender" name="gender" as="select" options={['Female', 'Male', 'Other', 'Prefer not to say']} required defaultValue={editing?.gender} error={errors.gender} /><Field label="Phone number" name="phone" required defaultValue={editing?.phone} error={errors.phone} /><Field label="Email address" name="email" type="email" defaultValue={editing?.email} error={errors.email} /><Field label="Address" name="address" defaultValue={editing?.address} wide /><Field label="City" name="city" required defaultValue={editing?.city} error={errors.city} /><Field label="State" name="state" defaultValue={editing?.state || 'Maharashtra'} /><Field label="Emergency contact" name="emergency" defaultValue={editing?.emergency} error={errors.emergency} /></FormSection><FormSection title="Identification"><Field label="Government ID type" name="govIdType" as="select" options={['Aadhaar card', 'Voter ID', 'PAN card', 'Other']} defaultValue={editing?.govIdType} /><Field label="Government ID number" name="govIdNumber" defaultValue={editing?.govIdNumber} /></FormSection><FormSection title="Social & family information"><Field label="Marital status" name="marital" as="select" options={['Single', 'Married', 'Widowed', 'Other']} defaultValue={editing?.marital} /><Field label="Occupation" name="occupation" defaultValue={editing?.occupation} /><Field label="Family members" name="familyMembers" type="number" min="0" defaultValue={editing?.familyMembers} error={errors.familyMembers} /><Field label="Monthly family income (₹)" name="income" type="number" min="0" defaultValue={editing?.income} error={errors.income} /><Field label="Education level" name="education" as="select" options={['No formal education', 'Primary', 'Secondary', 'Higher secondary', 'Graduate', 'Other']} defaultValue={editing?.education} /></FormSection><FormSection title="Needs assessment"><Field label="Primary need" name="primaryNeed" as="select" options={['Education', 'Healthcare', 'Mental Health', 'Financial Support', 'Employment', 'Women Empowerment', 'Food/Nutrition', 'Other']} defaultValue={editing?.primaryNeed} /><Field label="Secondary needs" name="secondaryNeeds" defaultValue={editing?.secondaryNeeds} /><Field label="Urgency" name="urgency" as="select" options={['Low', 'Medium', 'High', 'Critical']} defaultValue={editing?.urgency} /><Field label="Description of need" name="needDescription" as="textarea" wide defaultValue={editing?.needDescription} /></FormSection><FormSection title="Programme information"><Field label="Project / programme" name="program" as="select" options={programs} defaultValue={editing?.program} /><Field label="Registration date" name="registrationDate" type="date" defaultValue={editing?.registrationDateISO} error={errors.registrationDate} /><Field label="Assigned staff member" name="assignedStaff" defaultValue={editing?.assignedStaff || 'Anjali Joshi'} /><Field label="Beneficiary status" name="status" as="select" options={['Active', 'Inactive', 'Follow-up Required', 'Completed']} defaultValue={editing?.status || 'Active'} /></FormSection><div className="form-actions"><button type="button" className="button button-secondary" onClick={close}>Cancel</button><button type="submit" className="button button-primary" disabled={saving}>{saving ? 'Saving…' : editing ? 'Save changes' : 'Save beneficiary'}</button></div></form>}
    {(type === 'service' || type === 'followup') && <form className="simple-form" onSubmit={saveEntry}>{type === 'service' ? <><Field label="Service type" required name="type" as="select" options={['Counselling Session', 'Healthcare Support', 'Educational Material', 'Financial Assistance', 'Food Support', 'Skill Training', 'Other']} /><Field label="Date" required name="date" type="date" defaultValue="2026-09-28" /><Field label="Provider" name="provider" defaultValue="Anjali Joshi" /><Field label="Status" name="status" as="select" options={['Completed', 'Scheduled', 'In progress']} /><Field label="Description" name="description" as="textarea" wide /><Field label="Remarks" name="remarks" as="textarea" wide /></> : <><Field label="Follow-up date" required name="date" type="date" /><Field label="Reason" required name="reason" as="select" options={['Counselling Follow-up', 'Health check-in', 'Document collection', 'Programme review', 'Other']} /><Field label="Assigned staff" name="staff" defaultValue="Anjali Joshi" /><Field label="Status" name="status" as="select" options={['Pending', 'Completed', 'Rescheduled']} /><Field label="Notes" name="notes" as="textarea" wide /><Field label="Next follow-up" name="next" type="date" /></>}<div className="form-actions"><button type="button" className="button button-secondary" onClick={close}>Cancel</button><button className="button button-primary" type="submit">{type === 'service' ? 'Save service' : 'Schedule follow-up'}</button></div></form>}
    {type === 'document' && <form className="simple-form" onSubmit={(event) => { event.preventDefault(); const value = new FormData(event.currentTarget).get('name'); if (value) showToast('Document uploaded successfully.'); close() }}><Field label="Document name" name="name" required /><Field label="Document type" name="type" as="select" options={['Identity proof', 'Needs assessment', 'Medical record', 'Other']} /><Field label="Choose file" name="file" type="file" wide /><div className="form-actions"><button className="button button-secondary" type="button" onClick={close}>Cancel</button><button className="button button-primary">Upload document</button></div></form>}
    {type === 'deactivate' && <div className="confirm-content"><div className="confirm-icon"><UserRound size={21} /></div><p>Are you sure you want to deactivate <strong>{person?.name}</strong>? Their information will remain securely stored, and their status will change to Inactive.</p><div className="form-actions"><button className="button button-secondary" onClick={close}>Cancel</button><button className="button button-danger" onClick={deactivate} disabled={saving}>{saving ? 'Deactivating…' : 'Confirm deactivation'}</button></div></div>}
    {type === 'report' && <div className="report-preview"><div className="report-banner"><div className="brand-mark"><HeartHandshake size={20} /></div><div><b>HOPE</b><span>BENEFICIARY IMPACT SUMMARY</span></div><time>28 SEP 2026</time></div><div className="report-person"><div className="profile-avatar">{person?.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</div><div><h3>{person?.name}</h3><span>{person?.code} · {person?.city}, Maharashtra</span></div><span className={`status-pill ${statusClass(person?.status || 'Active')}`}><i />{person?.status}</span></div><div className="report-facts"><Detail label="Age / Gender" value={`${person?.age} years · ${person?.gender}`} /><Detail label="Primary need" value={person?.primaryNeed} /><Detail label="Current programme" value={person?.program} /><Detail label="Registration date" value={person?.registrationDate} /></div>{[['Needs assessment', person?.assessment || person?.needDescription], ['Services received', person?.services?.map((item) => typeof item === 'string' ? item : item.type).join(', ')], ['Programme participation', person?.program], ['Follow-up history', `${person?.followUps?.length || 0} recorded follow-ups`], ['Progress history', person?.progress?.join(' · ')]].map(([label, value]) => <div className="report-line" key={label}><strong>{label}</strong><p>{value || 'No records on file.'}</p></div>)}<div className="form-actions"><button className="button button-secondary" onClick={close}>Close preview</button><button className="button button-secondary" onClick={() => window.print()}><Download size={15} /> Download / print</button><button className="button button-primary" onClick={() => window.print()}><FileText size={15} /> Print report</button></div></div>}
  </section></div>
}
function FormSection({ title, children }) { return <fieldset className="form-section"><legend>{title}</legend><div className="form-grid">{children}</div></fieldset> }
function Field({ label, name, required = false, type = 'text', as, options = [], defaultValue, wide = false, min, max, error }) { const Tag = as || (type === 'file' ? 'input' : 'input'); return <label className={`form-field ${wide ? 'field-wide' : ''} ${error ? 'has-error' : ''}`}><span>{label}{required && <i> *</i>}</span>{Tag === 'textarea' ? <textarea name={name} required={required} defaultValue={defaultValue} rows="3" /> : Tag === 'select' ? <select name={name} required={required} defaultValue={defaultValue || ''}><option value="">Select {label.toLowerCase()}</option>{options.map((option) => <option key={option}>{option}</option>)}</select> : <input name={name} type={type} required={required} defaultValue={type !== 'file' ? defaultValue : undefined} min={min} max={max} />}{error && <small className="field-error">{error}</small>}</label> }

export default App
